from solution import max_sum


def test_issue_example():
    """Issue example max_sum([[1],[2,1],[3,3,2]],3)==6."""
    assert max_sum([[1], [2, 1], [3, 3, 2]], 3) == 6  # 1+2+3=6


def test_issue_single_element():
    """Maximum sum in the given right triangle with one row."""
    assert max_sum([[42]], 1) == 42  # single element 42


def test_issue_two_rows_left_best():
    """Maximum sum is best top-to-bottom adjacent path."""
    assert max_sum([[1], [10, 2]], 2) == 11  # 1+10=11


def test_issue_two_rows_right_best():
    """Maximum sum is best top-to-bottom adjacent path."""
    assert max_sum([[1], [2, 10]], 2) == 11  # 1+10=11


def test_issue_greedy_trap():
    """Maximum sum requires lookahead, not greedy choice."""
    assert max_sum([[1], [10, 1], [1, 1, 100]], 3) == 102  # 1+1+100=102


def test_issue_four_rows_classic():
    """Maximum sum in the given right triangle of four rows."""
    assert max_sum([[3], [7, 4], [2, 4, 6], [8, 5, 9, 3]], 4) == 23  # 3+7+4+9=23


def test_issue_uniform_triangle():
    """Maximum sum with all equal entries is sum of one path."""
    assert max_sum([[5], [5, 5], [5, 5, 5]], 3) == 15  # 5+5+5=15


def test_issue_all_negative():
    """Maximum sum in triangle with negative numbers."""
    assert max_sum([[-1], [-2, -1], [-3, -2, -1]], 3) == -3  # -1+-1+-1=-3


def test_contract_left_edge_best():
    """Contract: find maximum sum in given right triangle."""
    assert max_sum([[9], [8, 1], [7, 1, 1], [6, 1, 1, 1]], 4) == 30  # 9+8+7+6=30


def test_contract_right_edge_best():
    """Contract: find maximum sum in given right triangle."""
    assert max_sum([[1], [1, 2], [1, 1, 3], [1, 1, 1, 4]], 4) == 10  # 1+2+3+4=10
